import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  Pairs,
  RefName,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr02115Page({ role, notify }: PageProps) {
  const [workerId, setWorkerId] = useState<number | string>('');
  const [payDate, setPayDate] = useState('');
  const [applied, setApplied] = useState<{ workerId: number | string; payDate: string }>({ workerId: '', payDate: '' });
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error } = useData<Page>(
    () =>
      call<Page>('GET', '/daily-payrolls', role, undefined, {
        dailyWorkerId: applied.workerId,
        payDate: applied.payDate,
        page,
        size: SIZE,
      }),
    [role, applied, page],
  );

  const rows = data?.items ?? [];
  const total = data?.total ?? 0;
  const sumPay = rows.reduce((sum, r) => sum + Number(r.payAmount ?? 0), 0);
  const sumTax = rows.reduce((sum, r) => sum + Number(r.withholdingTax ?? 0), 0);

  const search = () => {
    setPage(0);
    setApplied({ workerId, payDate });
  };

  const reset = () => {
    setWorkerId('');
    setPayDate('');
    setPage(0);
    setApplied({ workerId: '', payDate: '' });
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Num value={total} />
      </section>
      <section className="box span-4">
        <h2>지급 금액 (현재 쪽)</h2>
        <Num value={sumPay} />
      </section>
      <section className="box span-4">
        <h2>원천징수세액 (현재 쪽)</h2>
        <Num value={sumTax} />
      </section>
      <section className="box span-12">
        <h2>이체 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="일용직 사원">
            <LookupSelect table="daily_worker" role={role} value={workerId} onChange={setWorkerId} placeholder="전체" />
          </Field>
          <Field label="급여 지급일">
            <DateInput value={payDate} onChange={setPayDate} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          rows={rows}
          onRowClick={(row) => setSelected(row)}
          empty="조회된 급여 내역이 없습니다."
          columns={[
            {
              key: 'dailyWorkerId',
              label: '일용직 사원',
              render: (r) => <RefName table="daily_worker" role={role} value={r.dailyWorkerId} />,
            },
            { key: 'payDate', label: '급여 지급일', render: (r) => <DateText value={r.payDate} /> },
            { key: 'workDays', label: '근무일수', render: (r) => <Num value={r.workDays} /> },
            { key: 'payAmount', label: '지급 금액', render: (r) => <Num value={r.payAmount} /> },
            { key: 'withholdingTax', label: '원천징수세액', render: (r) => <Num value={r.withholdingTax} /> },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r.closingStatus} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {selected ? (
        <Drawer title="일용직 급여 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['일용직 급여 ID', String(selected.dailyPayrollId ?? '')],
              ['일용직 사원', <RefName table="daily_worker" role={role} value={selected.dailyWorkerId} />],
              ['급여 지급일', <DateText value={selected.payDate} />],
              ['근무일수', <Num value={selected.workDays} />],
              ['지급 금액', <Num value={selected.payAmount} />],
              ['원천징수세액', <Num value={selected.withholdingTax} />],
              ['마감 상태', <Badge value={selected.closingStatus} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
